// Activity formats share Oxford lesson editing, not a single quiz mechanic.
const ACTIVITIES={
 gameshow:{name:'Gameshow Quiz',icon:'🎤',mode:'TEAM',input:'choice',subjects:['english','math'],rule:'Teams take turns answering for points and streak bonuses. Each team has one 50:50 lifeline.'},
 typed:{name:'Type the Answer',icon:'⌨️',input:'text',subjects:['english','math'],rule:'Type your answer, then check it. Capitalization and extra spaces do not matter.'},
 flip:{name:'Flip Tiles',icon:'🃏',mode:'CLASS',input:'text',subjects:['english','math'],rule:'Choose a tile to reveal its question, flip for the answer, then mark it learned or revisit it. Learn every tile together.'},
 wordsearch:{name:'Wordsearch',icon:'🔎',input:'word',subjects:['english'],rule:'Find the listed words horizontally, vertically or diagonally. Tap the first and last letter; words may run backwards.'},
 spell:{name:'Spell the Word',icon:'🔤',input:'word',subjects:['english'],rule:'Read the clue and tap the scrambled letters in the correct order. Tap a chosen letter to return it.'},
 hangman:{name:'Hangman',icon:'🪁',input:'word',subjects:['english'],rule:'Use the clue to guess letters. Six misses lose the word. Each new word gives you a fresh kite and six guesses.'},
 diagram:{name:'Labelled Diagram',icon:'🧬',mode:'CLASS',input:'diagram',subjects:['biology'],rule:'Read the label and tap its correct numbered marker on the diagram. Teachers can upload a diagram and place each label marker.'},
 crossword:{name:'Crossword',icon:'🧩',input:'word',subjects:['english'],rule:'Select a numbered clue and type its word. Correct answers fill the crossing letters. Solve every clue.'},
 maze:{name:'Maze Chase',icon:'👻',input:'choice',subjects:['english','math'],rule:'Move with arrows or the on-screen pad. Reach the letter of the correct answer while avoiding the chaser. Three mistakes or catches end the run.'},
 truefalse:{name:'True or False',icon:'✅',input:'boolean',subjects:['english','math'],rule:'Read the statement and decide whether it is true or false. Discuss the explanation after each decision.'},
 fruit:{name:'Flying Fruit',icon:'🍉',input:'choice',subjects:['english','math'],rule:'Catch the flying fruit carrying the correct answer. A wrong catch costs a heart. You have three hearts.'},
 pair:{name:'Pair or No Pair',icon:'🧦',input:'text',subjects:['english','math'],rule:'Decide whether the displayed question and answer belong together. Correct decisions build a bonus streak.'},
 balloon:{name:'Balloon Pop',icon:'🎈',input:'choice',subjects:['english','math'],rule:'Pop the balloon carrying the correct answer. Wrong balloons cost a heart; finish before all three hearts are gone.'},
 airplane:{name:'Airplane',icon:'✈️',input:'choice',subjects:['english','math'],rule:'Steer up or down into the correct answer lane before the gates reach your plane. Arrow buttons and keyboard arrows both work. Three crashes end the flight.'},
 imagequiz:{name:'Image Quiz',icon:'🖼️',input:'image',subjects:['math'],rule:'Study the picture and choose the answer. Teachers can upload an image for each question.'},
 mole:{name:'Whack-a-mole',icon:'🔨',input:'choice',subjects:['english','math'],rule:'Watch nine holes for answer moles that pop up and duck down. Tap the correct answer or press its hole number (1–9). Wrong hits cost a heart. Freeze the moles for more reading time.'},
 rank:{name:'Rank Order',icon:'🏅',input:'order',subjects:['math'],rule:'Move the entries up or down until they are in the requested order, then check the ranking.'},
 speedsort:{name:'Speed Sorting',icon:'⚡',input:'choice',subjects:['english','math'],rule:'Sort each prompt into the right category before 60 seconds expire. The next item appears automatically; correct answers earn a time bonus.'},
 memory:{name:'Watch and Memorize',icon:'👀',mode:'CLASS',input:'text',subjects:['english','math'],rule:'Watch the sequence together, then reproduce it by tapping the cards in order. Three mistakes end the challenge.'},
 winlose:{name:'Win or Lose Quiz',icon:'🎲',mode:'TEAM',input:'choice',subjects:['english','math'],rule:'Teams start with 100 points. Choose a 25, 50 or 100 point stake before answering. Correct answers win the stake; mistakes lose it. Highest final score wins.'},
 maths:{name:'Maths Generator',icon:'🧮',input:'generator',subjects:['math'],rule:'Generate fresh arithmetic with your chosen operations, number range and question count. Type each answer to check it.'},
 magnets:{name:'Word Magnets',icon:'🧲',input:'order',subjects:['english'],rule:'Tap or drag word magnets into a sentence. Tap a placed word to return it, or clear the board and try again.'}
};
const ACT_WORDS={7:[['Willing to face danger','BRAVE'],['Exact and clearly stated','PRECISE'],['More than enough','ABUNDANT'],['Not willing to do something','RELUCTANT'],['Dangerous to travel across','TREACHEROUS'],['Lasting only a short time','BRIEF']],8:[['A position a writer argues for','CLAIM'],['Facts used to support a claim','EVIDENCE'],['A response that challenges an opposing argument','REBUTTAL'],['Able to be trusted','RELIABLE'],['Reasoning that connects ideas','LOGIC'],['A statement that follows from evidence','CONCLUSION']]};
for(const [id,c] of Object.entries(ACTIVITIES)){
 c.mode ||= 'SOLO';c.color=['#6746b5','#147f8d','#ba326e','#215aa3'][Object.keys(ACTIVITIES).indexOf(id)%4];FORMATS[id]={...c,description:c.rule,instructions:c.rule};
 for(const subject of c.subjects)for(const grade of [7,8]){
  const source=GAMES.find(g=>g.id===`${subject==='biology'?'english':subject}-${grade}-${id==='speedsort'?'sort':id==='magnets'?'order':'quiz'}`),g=JSON.parse(JSON.stringify(source));g.id=`${subject}-${grade}-${id}`;g.format=id;g.subject=subject;g.grade=grade;g.minutes='10–15';
  if(c.input==='word'||id==='typed'&&subject==='english'||id==='memory'&&subject==='english'){g.topic=grade===7?'Vocabulary and spelling':'Argument and evidence vocabulary';g.items=ACT_WORDS[grade].map(([prompt,answer])=>({prompt,answer,options:[],hint:'',explanation:''}));}
  if(id==='memory'&&subject==='math'){g.topic='Recall a number sequence';g.items=[3,8,12,5,16,7].map(n=>({prompt:'Remember this value',answer:String(grade===8?n*3:n),options:[],hint:'',explanation:''}));}
  if(id==='truefalse'){g.items=g.items.map((q,i)=>({prompt:`${q.prompt} Answer: ${i%2?q.options[0]:q.answer}.`,answer:i%2?'False':'True',options:[],hint:'',explanation:`The correct answer to the original question is ${q.answer}.`}));}
  if(id==='diagram'){g.topic=grade===7?'Animal cell structures':'Cell structures and their functions';g.items=[['Cell membrane','The boundary that controls what enters the cell',88,51],['Cytoplasm','The fluid in which cell reactions occur',20,48],['Nucleus','The structure containing genetic information',53,51],['Mitochondrion','The organelle releasing energy through respiration',72,32],['Vacuole','A small storage compartment',30,65],['Ribosome','A tiny structure that makes proteins',72,70]].map(([answer,fn,x,y])=>({prompt:grade===7?`Find the ${answer.toLowerCase()}.`:fn,answer,point:{x,y},options:[],hint:'',explanation:fn}));}
  if(id==='imagequiz'){g.topic=grade===7?'Reading geometry diagrams':'Geometry and scale';g.items=Array.from({length:6},(_,i)=>{const w=4+i,h=2+i,area=w*h,answer=String(grade===7?2*(w+h):area);return {prompt:grade===7?'What is the rectangle’s perimeter in cm?':'What is the rectangle’s area in cm²?',answer,options:[String(Number(answer)+3),String(Number(answer)+7),String(Number(answer)-2)],visual:'rectangle',width:w,height:h,hint:'',explanation:grade===7?'Add all four sides.':'Multiply length by width.'};});}
  if(id==='magnets'){g.topic=grade===7?'Building clear sentences':'Complex sentences and arguments';if(grade===7)g.items=g.items.map(q=>({...q,answer:q.answer.replaceAll('|',' ').split(/\s+/).join('|')}));else g.items=['Although the evidence seems convincing, we should check its source.','The writer supports her claim with reliable evidence.','If the results are repeated, the conclusion becomes more reliable.','However, the counterargument raises an important question.','Because the source is biased, we need another perspective.','The conclusion should follow logically from the evidence.'].map(answer=>({prompt:'Build the sentence. Begin with '+answer.split(' ')[0],answer:answer.split(' ').join('|'),options:[],hint:'',explanation:''}));}
  if(id==='rank'){g.topic=grade===7?'Ordering signed numbers':'Ordering powers and roots';g.items=Array.from({length:6},(_,i)=>({prompt:'Order these values from smallest to largest.',answer:grade===7?`${-9-i}|${-2-i}|${3+i}|${8+i}`:`${i+1}²|${i+2}²|${i+3}²|${i+4}²`,options:[],hint:'',explanation:'Compare the values before choosing their order.'}));}
  g.title=`${c.name}: ${g.topic}`;GAMES.push(g);
 }
}
